const FILE_TYPES = {
    video: ["mp4", "webm", "avi", "mpg", "mpeg", "mkv", "rm", "rmvb", "mov", "wmv", "asf", "ts", "flv", "3gp", "m4v"],
    audio: ["mp3", "flac", "wav", "ogg", "m4a", "aac", "wma", "alac"],
    image: ["bmp", "jpg", "jpeg", "png", "gif", "svg", "tiff", "ico"],
    code: ["php", "css", "go", "java", "js", "json", "txt", "sh", "html", "xml", "py", "rb", "c", "cpp", "h", "hpp"],
    archive: ["zip", "rar", "tar", "7z", "gz"],
    document: ["pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx"],
    markdown: ["md"]
};

const GDOC_TYPES = {
    "application/vnd.google-apps.document": {
        icon: '<i class="bi bi-file-earmark-text gdi-icon-doc"></i>',
        name: "Google Doc",
        formats: [
            {label: "PDF", ext: "pdf"},
            {label: "DOCX", ext: "docx"},
            {label: "TXT", ext: "txt"}
        ]
    },
    "application/vnd.google-apps.spreadsheet": {
        icon: '<i class="bi bi-file-earmark-spreadsheet gdi-icon-doc"></i>',
        name: "Google Sheet",
        formats: [
            {label: "PDF", ext: "pdf"},
            {label: "XLSX", ext: "xlsx"},
            {label: "CSV", ext: "csv"}
        ]
    },
    "application/vnd.google-apps.presentation": {
        icon: '<i class="bi bi-file-earmark-slides gdi-icon-doc"></i>',
        name: "Google Slides",
        formats: [
            {label: "PDF", ext: "pdf"},
            {label: "PPTX", ext: "pptx"}
        ]
    }
};

// ============================================================
// SISTEMA DE USUÁRIO COM PERSISTÊNCIA CORRIGIDO
// ============================================================
const GDIUserSystem = {
    currentUser: null,
    
    init() {
        this.currentUser = this.getCurrentUser();
        if (!this.currentUser) {
            this.currentUser = this.createDefaultUser();
            this.saveUser(this.currentUser);
        }
        this.loadUserPreferences();
        console.log('[GDIUserSystem] Usuário inicializado:', this.currentUser.name);
    },
    
    getCurrentUser() {
        try {
            const userData = localStorage.getItem('gdi-current-user');
            return userData ? JSON.parse(userData) : null;
        } catch(e) {
            console.error('Erro ao carregar usuário:', e);
            return null;
        }
    },
    
    createDefaultUser() {
        return {
            id: 'user_' + Date.now(),
            name: 'Estudante',
            createdAt: new Date().toISOString(),
            preferences: {
                theme: 'dark',
                playerType: 'plyr',
                autoplay: true,
                defaultVolume: 0.7,
                sleepModeEnabled: true,
                pomodoroSettings: {
                    work: 25,
                    short: 5,
                    long: 15,
                    sessions: 4
                }
            },
            notes: {},
            videoProgress: {},
            watchHistory: [],
            completedLessons: {}
        };
    },
    
    saveUser(user) {
        try {
            localStorage.setItem('gdi-current-user', JSON.stringify(user));
            this.currentUser = user;
            return true;
        } catch(e) {
            console.error('Erro ao salvar usuário:', e);
            return false;
        }
    },
    
    loadUserPreferences() {
        if (this.currentUser && this.currentUser.preferences) {
            const theme = this.currentUser.preferences.theme;
            if (theme) {
                applyTheme(theme);
            }
            if (window.player_config) {
                window.player_config.player = this.currentUser.preferences.playerType || 'plyr';
            }
        }
    },
    
    updatePreferences(newPrefs) {
        if (!this.currentUser) return;
        this.currentUser.preferences = {
            ...this.currentUser.preferences,
            ...newPrefs
        };
        this.saveUser(this.currentUser);
    },
    
    addNote(videoId, note) {
        if (!this.currentUser) return;
        if (!this.currentUser.notes) this.currentUser.notes = {};
        if (!this.currentUser.notes[videoId]) {
            this.currentUser.notes[videoId] = [];
        }
        note.id = 'note_' + Date.now();
        note.createdAt = new Date().toISOString();
        this.currentUser.notes[videoId].push(note);
        this.saveUser(this.currentUser);
        return note;
    },
    
    removeNote(videoId, noteId) {
        if (!this.currentUser || !this.currentUser.notes || !this.currentUser.notes[videoId]) return;
        this.currentUser.notes[videoId] = this.currentUser.notes[videoId].filter(n => n.id !== noteId);
        this.saveUser(this.currentUser);
    },
    
    getNotes(videoId) {
        return this.currentUser?.notes?.[videoId] || [];
    },
    
    saveVideoProgress(videoId, progress) {
        if (!this.currentUser) return;
        if (!this.currentUser.videoProgress) this.currentUser.videoProgress = {};
        if (!this.currentUser.watchHistory) this.currentUser.watchHistory = [];

        this.currentUser.videoProgress[videoId] = {
            ...progress,
            updatedAt: new Date().toISOString()
        };
        
        const historyEntry = {
            videoId,
            name: progress.name,
            progress: progress.duration > 0 ? progress.currentTime / progress.duration : 0,
            timestamp: new Date().toISOString(),
            url: progress.url
        };
        
        // Evita duplicatas excessivas no histórico recente
        this.currentUser.watchHistory = this.currentUser.watchHistory.filter(item => item.videoId !== videoId);
        this.currentUser.watchHistory.unshift(historyEntry);
        this.currentUser.watchHistory = this.currentUser.watchHistory.slice(0, 30);
        
        this.saveUser(this.currentUser);
    },
    
    getVideoProgress(videoId) {
        return this.currentUser?.videoProgress?.[videoId] || null;
    },
    
    getContinueWatching() {
        if (!this.currentUser || !this.currentUser.watchHistory) return [];
        return this.currentUser.watchHistory
            .filter(item => item.progress > 0.02 && item.progress < 0.95)
            .slice(0, 8);
    }
};

