// ============================================================
// FUNÇÕES UTILITÁRIAS
// ============================================================
function isFileType(i, e) {
    return FILE_TYPES[e] && FILE_TYPES[e].includes(i?.toLowerCase());
}

function getFileIcon(i) {
    const e = i?.toLowerCase();
    return isFileType(e, "video") ? '<i class="bi bi-camera-video-fill gdi-icon-video" style="color:#3b82f6;"></i>' :
           isFileType(e, "audio") ? '<i class="bi bi-music-note-beamed gdi-icon-audio" style="color:#ec4899;"></i>' :
           isFileType(e, "image") ? '<i class="bi bi-image gdi-icon-image" style="color:#10b981;"></i>' :
           isFileType(e, "archive") ? '<i class="bi bi-file-earmark-zip-fill gdi-icon-archive" style="color:#f59e0b;"></i>' :
           isFileType(e, "markdown") ? '<i class="bi bi-markdown-fill gdi-icon-md" style="color:#6366f1;"></i>' :
           e === "pdf" ? '<i class="bi bi-file-earmark-pdf-fill gdi-icon-pdf" style="color:#ef4444;"></i>' :
           isFileType(e, "code") ? '<i class="bi bi-code-slash gdi-icon-code" style="color:#8b5cf6;"></i>' :
           '<i class="bi bi-file-earmark gdi-icon-file"></i>';
}

const Os = {
    isWindows: navigator.userAgent.toUpperCase().indexOf("WIN") > -1,
    isMac: navigator.userAgent.toUpperCase().indexOf("MAC") > -1,
    isMacLike: /(Mac|iPhone|iPod|iPad)/i.test(navigator.userAgent),
    isIos: /(iPhone|iPod|iPad)/i.test(navigator.userAgent),
    isMobile: /Android|webOS|iPhone|iPad|iPod|iOS|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)
};

function getDocumentHeight() {
    const i = document;
    return Math.max(i.body.scrollHeight, i.documentElement.scrollHeight, i.body.offsetHeight, i.documentElement.offsetHeight, i.body.clientHeight, i.documentElement.clientHeight);
}

function getQueryVariable(i) {
    const t = window.location.search.substring(1).split("&");
    for (let n = 0; n < t.length; n++) {
        const a = t[n].split("=");
        if (a[0] == i) return a.slice(1).join("=");
    }
    return false;
}

function escHtml(i) {
    return String(i || "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#x27;");
}

function trimChar(i, e) {
    return e ? i.replace(new RegExp("^\\" + e + "+|\\" + e + "+$", "g"), "") : i.trim();
}

function applyTheme(i) {
    document.documentElement.setAttribute("data-bs-theme", i);
    const e = document.getElementById("theme-icon");
    e && (e.className = i === "dark" ? "bi bi-moon-stars" : "bi bi-sun");
}

function toggleTheme() {
    const e = (document.documentElement.getAttribute("data-bs-theme") || "dark") === "dark" ? "light" : "dark";
    localStorage.setItem("gdi-theme", e);
    applyTheme(e);
    GDIUserSystem.updatePreferences({theme: e});
}

function sleep(i) { return new Promise(e => setTimeout(e, i)); }

function formatFileSize(i) {
    const e = Number(i);
    return isNaN(e) || e < 0 ? "" :
           e >= 1099511627776 ? (e / 1099511627776).toFixed(2) + " TB" :
           e >= 1073741824 ? (e / 1073741824).toFixed(2) + " GB" :
           e >= 1048576 ? (e / 1048576).toFixed(2) + " MB" :
           e >= 1024 ? (e / 1024).toFixed(2) + " KB" :
           e > 1 ? e + " bytes" : e === 1 ? "1 byte" : "0 bytes";
}

function formatDateTime(i) { return i ? new Date(i).toLocaleString() : ""; }
const utc2delhi = formatDateTime;

function formatTime(seconds) {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = Math.floor(seconds % 60);
    if (h > 0) return `${h}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

// ============================================================
// SISTEMA DE DEBUG
// ============================================================
const GDIDebug = (() => {
    const i = [];
    let e = null;
    function t() { return new Date().toISOString().slice(11, 23); }
    function n() {
        if (e || (e = document.getElementById("gdi-debug-log")), !e) return;
        const d = {req: "#da77f2", api: "#69db7c", error: "#ff6b6b", warn: "#ffa94d", info: "#74c0fc"};
        e.innerHTML = i.map(r => `<div class="gdi-dbg-entry"><span class="gdi-dbg-ts">${r.ts}</span><span style="color:${d[r.type]||'#aaa'}">[${r.type.toUpperCase()}]</span> ${escHtml(r.label)}</div>`).join("") || '<span class="gdi-dbg-empty">No entries yet.</span>';
        e.scrollTop = e.scrollHeight;
    }
    function a(d, o, s) { window.UI?.debug_mode && (i.push({ts: t(), type: d, label: o, data: s}), n()); }
    function c() {
        e = document.getElementById("gdi-debug-log");
        const d = document.createElement("style");
        d.textContent = ".gdi-debug-wrap{width:100%;background:#0d1117;border-top:2px solid #f0883e;font-family:monospace;font-size:12px;}.gdi-debug-head{display:flex;justify-content:space-between;padding:8px 14px;background:#161b22;cursor:pointer;color:#8b949e;}#gdi-debug-log{max-height:200px;overflow-y:auto;padding:10px;color:#e6edf3;}";
        document.head.appendChild(d);
    }
    return {log: a, attach: c, clear: () => { i.length = 0; n(); }};
})();

