// INICIALIZAÇÃO DA APLICAÇÃO & UI GERAL
// ============================================================
function init() {
    const UI = window.UI || {};
    document.siteName = $("title").html();
    
    const html = `
    <div id="nav"></div>
    <div id="content" style="padding-top:76px;${UI.fixed_footer ? " padding-bottom:120px;" : ""}"></div>
    
    <div class="modal fade" id="SearchModel" data-bs-backdrop="static" data-bs-keyboard="false" tabindex="-1" aria-hidden="true">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content" style="background:var(--gdi-surface);color:var(--gdi-text);border:1px solid var(--gdi-border);">
          <div class="modal-header border-bottom border-secondary">
            <h5 class="modal-title" id="SearchModelLabel">Resultado</h5>
            <button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div class="modal-body" id="modal-body-space"></div>
        </div>
      </div>
    </div>
    
    <div id="gdi-toast-container"></div>
    <footer class="gdi-footer text-center py-4" style="color:var(--gdi-text-muted);font-size:13px;border-top:1px solid var(--gdi-border);margin-top:40px;">
      <span>&copy; ${new Date().getFullYear()} ${UI.company_name || 'Drive'} &middot; Plataforma de Estudos Acadêmicos</span>
    </footer>`;
    
    $("body").html(html);
}

function title(i) {
    try { i = decodeURI(i); } catch {}
    const e = window.current_drive_order || 0;
    const t = (window.drive_names && window.drive_names[e]) || "Drive";
    i = i.replace(`/${e}:`, "");
    const n = window.MODEL || {};
    n.is_search_page ? $("title").html(`${t} - Busca: ${n.q || ""}`) : $("title").html(`${t} - ${i}`);
}

function nav(i) {
    const e = window.MODEL || {};
    const t = window.current_drive_order || 0;
    const n = (window.drive_names && window.drive_names[t]) || "Drive";
    const a = window.drive_names || [];
    const UI = window.UI || {};
    const c = e.is_search_page && e.q || "";
    
    let l = "";
    a.forEach((r, p) => {
        l += `<li><a class="dropdown-item${p === t ? " active" : ""}" href="/${p}:/"><i class="bi bi-folder2-open me-2"></i>${r}</a></li>`;
    });
    
    const d = `<i class="bi bi-mortarboard-fill"></i> <span>${UI.logo_link_name || 'Academia'}</span>`;
    const o = (e.root_type === undefined || e.root_type < 2) ? `
      <div class="gdi-nav-search d-none d-md-block">
        <form class="gdi-search-form" method="get" action="/${t}:search">
          <input class="gdi-search-input" name="q" type="search" placeholder="Pesquisar aulas e materiais…" value="${escHtml(c)}">
          <i class="bi bi-search"></i>
        </form>
      </div>` : "";
    
    const s = `
    <nav class="gdi-nav">
      <div class="gdi-nav-inner">
        <a class="gdi-logo" href="/${t}:/">${d}</a>
        ${o}
        <div class="gdi-nav-actions d-flex align-items:center; gap:12px;">
          <div class="dropdown">
            <button class="gdi-btn gdi-btn-ghost dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false">
              <i class="bi bi-grid-3x3-gap-fill"></i> ${escHtml(n)}
            </button>
            <ul class="dropdown-menu dropdown-menu-end shadow">${l}</ul>
          </div>
          <button id="theme-toggle" class="gdi-btn gdi-btn-ghost" onclick="toggleTheme()" title="Alternar Tema">
            <i class="bi bi-moon-stars" id="theme-icon"></i>
          </button>
        </div>
      </div>
    </nav>`;
    
    $("#nav").html(s);
    applyTheme(localStorage.getItem("gdi-theme") || "dark");
}

function render(i) {
    if (i.indexOf("?") >= 0) i = i.substr(0, i.indexOf("?"));
    title(i);
    nav(i);
    
    const e = /\/\d+:$/g;
    if (i.includes("/fallback")) {
        window.scroll_status = {event_bound: false, loading_lock: false};
        const t = getQueryVariable("a");
        const n = decodeURIComponent(getQueryVariable("id") || "");
        return t ? fallback(n, true) : list(null, n, true);
    } else if (window.MODEL?.is_search_page) {
        window.scroll_status = {event_bound: false, loading_lock: false};
        render_search_result_list();
    } else if (i.match(e) || i.slice(-1) == "/") {
        window.scroll_status = {event_bound: false, loading_lock: false};
        list(i);
    } else {
        file(i);
    }
}

// ============================================================
// FUNÇÕES DE LISTAGEM DE DIRETÓRIOS & CURSOS
// ============================================================
function requestListPath(i, e, t, n, a = 3, c = false) {
    const l = {
        id: e.id || "",
        type: "folder",
        password: e.password || "",
        page_token: e.page_token || "",
        page_index: e.page_index || 0
    };
    
    $("#update").show();
    $("#update").html('<div class="gdi-alert alert alert-info py-2">Sincronizando conteúdos...</div>');
    c && (i = "/0:fallback");
    
    async function o(s) {
        try {
            const r = await fetch(c ? "/0:fallback" : i, {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify(l)
            });
            if (!r.ok) throw new Error("Erro na requisição: " + r.status);
            const p = await r.json();
            
            if (p && p.error && p.error.code === 401) {
                $("#update").hide();
                askPassword(i);
            } else if (p && p.data) {
                t(p, i, l);
                $("#update").hide();
            }
        } catch (r) {
            if (s > 0) {
                await sleep(2000);
                await o(s - 1);
            } else {
                $("#update").html('<div class="gdi-alert alert alert-danger">Falha ao conectar ao servidor.</div>');
                $("#spinner").remove();
            }
        }
    }
    o(a);
}

function list(i, e = "", t = false) {
    const n = window.location.pathname;
    const a = trimChar(n, "/").split("/");
    let c = "/", l = '<li><a href="/">Início</a></li><li class="gdi-bc-sep">/</li>';
    
    if (a.length > 1) {
        for (const p in a) {
            const g = a[p];
            let f;
            try { f = decodeURIComponent(g); } catch { f = g; }
            f = f.replace(/\//g, "%2F");
            const u = f.match(/^(\d+):$/);
            const h = u && window.drive_names && window.drive_names[+u[1]] || f;
            const m = h.length > 22 ? h.slice(0, 18) + "…" : h;
            c += g + "/";
            if (!m) break;
            
            if (Number(p) === a.length - 1) {
                l += `<li class="gdi-bc-cur" title="${escHtml(h)}">${escHtml(m)}</li>`;
            } else {
                l += `<li><a href="${c}" title="${escHtml(h)}">${escHtml(m)}</a></li><li class="gdi-bc-sep">/</li>`;
            }
        }
    }
    
    const d = `
    <div class="gdi-wrap">
      <div id="update"></div>
      <div id="continue-watching-container"></div>
      <div class="gdi-breadcrumb-wrap">
        <ol class="gdi-bc">${l}</ol>
      </div>
      <div class="gdi-panel">
        <div class="gdi-toolbar p-3 border-bottom border-secondary d-flex align-items:center">
          <input id="folder-filter" class="gdi-search-input" style="width:100%;max-width:400px;" type="search" placeholder="Filtrar aulas e arquivos nesta pasta…" autocomplete="off">
        </div>
        <div class="gdi-list-header">
          <span class="gdi-col-icon"></span>
          <span class="gdi-col-name">Título da Aula / Módulo</span>
          <span class="gdi-col-size">Tamanho</span>
          <span class="gdi-col-date">Modificado</span>
          <span class="gdi-col-acts text-end">Ações</span>
        </div>
        <div id="list"></div>
        <div id="count" class="p-3 text-muted text-center" style="font-size:13px;"></div>
      </div>
    </div>`;
    
    $("#content").html(d);
    renderContinueWatchingBanner();
    
    const o = localStorage.getItem("password" + i);
    $("#list").html('<div class="d-flex justify-content:center py-5" id="spinner"><div class="spinner-border text-primary" role="status"></div></div>');
    
    function s(p, g, f) {
        $("#spinner").remove();
        t ? append_files_to_fallback_list(g, p.data.files) : append_files_to_list(g, p.data.files);
    }
    
    t ? requestListPath(i, {id: e, password: o}, s, null, 3, true) : requestListPath(i, {password: o}, s, null);
    
    // Filtro interativo instantâneo
    document.getElementById("folder-filter")?.addEventListener("input", function() {
        const val = this.value.toLowerCase();
        document.querySelectorAll("#list .gdi-row").forEach(row => {
            const name = (row.dataset.name || "").toLowerCase();
            row.style.display = name.includes(val) ? "" : "none";
        });
    });
}

// Banner "Continuar Assistindo" Funcional na Raiz / Pastas
function renderContinueWatchingBanner() {
    const history = GDIUserSystem.getContinueWatching();
    const container = document.getElementById('continue-watching-container');
    if (!container || history.length === 0) return;
    
    let html = `
    <div class="gdi-panel p-4 mb-4" style="background:linear-gradient(135deg, rgba(59,130,246,0.08), rgba(139,92,246,0.05)); border:1px solid rgba(59,130,246,0.2);">
        <div class="d-flex align-items:center justify-content:between mb-3">
            <h5 class="mb-0 fw-bold" style="font-size:16px;display:flex;align-items:center;gap:8px;">
                <i class="bi bi-play-circle-fill text-primary"></i> Continuar Estudos
            </h5>
        </div>
        <div class="d-flex gap-3 overflow-x-auto pb-2" style="scrollbar-width:thin;">
    `;
    
    history.forEach(item => {
        const pct = Math.round((item.progress || 0) * 100);
        html += `
        <div class="p-3 rounded flex-shrink-0" style="width:240px;background:var(--gdi-surface);border:1px solid var(--gdi-border);cursor:pointer;transition:transform 0.2s;" onclick="window.location.href='${item.url}'" onmouseover="this.style.transform='translateY(-2px)'" onmouseout="this.style.transform='none'">
            <div class="fw-semibold text-truncate mb-2" style="font-size:13px;" title="${escHtml(item.name)}">${escHtml(item.name)}</div>
            <div class="progress mb-2" style="height:5px;background:rgba(255,255,255,0.1);">
                <div class="progress-bar bg-primary" role="progressbar" style="width:${pct}%"></div>
            </div>
            <div class="d-flex justify-content:between text-muted" style="font-size:11px;">
                <span>Progresso</span>
                <span class="text-primary fw-bold">${pct}%</span>
            </div>
        </div>`;
    });
    
    html += `</div></div>`;
    container.innerHTML = html;
}

function append_files_to_list(i, e) {
    const UI = window.UI || {};
    const t = $("#list");
    let c = "", totalSize = 0, fileCount = 0;
    
    for (const o in e) {
        const s = e[o];
        const r = encodeURIComponent(s.name).replace(/\//g, "%2F") + "/";
        const p = i + r.replace(/#/g, "%23").replace(/\?/g, "%3F");
        s.modifiedTime = utc2delhi(s.modifiedTime);
        
        if (s.mimeType == "application/vnd.google-apps.folder") {
            c += `
            <a href="${p}" class="gdi-row" data-name="${escHtml(s.name.toLowerCase())}">
              <span class="gdi-row-icon"><i class="bi bi-folder-fill" style="color:#f59e0b;"></i></span>
              <span class="gdi-row-name">${escHtml(s.name)}</span>
              <span class="gdi-row-size text-muted">-</span>
              <span class="gdi-row-date text-muted" style="font-size:12px;">${UI.display_time ? s.modifiedTime : ""}</span>
              <span class="gdi-row-acts text-end"><i class="bi bi-chevron-right text-muted"></i></span>
            </a>`;
        } else {
            const bytes = Number(s.size || 0);
            totalSize += bytes;
            fileCount++;
            s.sizeFormatted = formatFileSize(s.size);
            const f = s.fileExtension;
            const u = UI.second_domain_for_dl ? UI.downloaddomain + s.link : window.location.origin + s.link;
            const h = encodeURIComponent(s.name);
            const viewUrl = i + h + "?a=view";
            const isCompleted = GDIUserSystem.currentUser?.completedLessons?.[s.id] ? 'checked' : '';
            
            c += `
            <div class="gdi-row" data-name="${escHtml(s.name.toLowerCase())}">
              <span class="gdi-row-icon">${getFileIcon(f)}</span>
              <span class="gdi-row-name">
                <a href="${viewUrl}" class="text-decoration-none text-reset" title="${escHtml(s.name)}">${escHtml(s.name)}</a>
              </span>
              <span class="gdi-row-size text-muted" style="font-size:12px;">${s.sizeFormatted}</span>
              <span class="gdi-row-date text-muted" style="font-size:12px;">${UI.display_time ? s.modifiedTime : ""}</span>
              <span class="gdi-row-acts text-end d-flex align-items-center justify-content-end gap-2">
                <div class="form-check" title="Marcar aula como concluída" style="margin:0;">
                  <input class="form-check-input" type="checkbox" ${isCompleted} onchange="toggleLessonComplete('${s.id}', this)" style="cursor:pointer;" id="chk_${s.id}">
                </div>
                <a class="gdi-btn gdi-btn-ghost py-1 px-2" href="${u}" title="Baixar Material" download><i class="bi bi-download"></i></a>
              </span>
            </div>`;
        }
    }
    
    t.append(c);
    const countEl = document.getElementById("count");
    if (countEl) {
        countEl.innerHTML = `${fileCount} arquivos encontrados (${formatFileSize(totalSize)})`;
    }
}

function toggleLessonComplete(fileId, checkbox) {
    const user = GDIUserSystem.currentUser;
    if (!user) return;
    if (!user.completedLessons) user.completedLessons = {};
    
    user.completedLessons[fileId] = checkbox.checked;
    GDIUserSystem.saveUser(user);
    showToast(checkbox.checked ? 'Aula concluída com sucesso! 🏆' : 'Aula marcada como pendente.');
}

function append_files_to_fallback_list(i, e) {
    append_files_to_list(i, e);
}

function askPassword(i) {
    $("#spinner").remove();
    const e = prompt("Conteúdo protegido. Insira a senha de acesso:", "");
    e != null && e != "" ? (localStorage.setItem("password" + i, e), list(i)) : history.go(-1);
}

// ============================================================
// VISUALIZADOR DE ARQUIVOS E VÍDEOS (PLAYER ACADÊMICO)
// ============================================================
async function fallback(i, e) {
    if (e) {
        const t = await getCookie("root_id") || "";
        $("#content").html('<div class="gdi-wrap text-center py-5"><div class="spinner-border text-primary" role="status"></div></div>');
        fetch("/0:fallback", {
            method: "POST",
            headers: {"Content-Type": "application/json"},
            body: JSON.stringify({id: i})
        }).then(n => n.json()).then(n => dispatchFileView(n, t)).catch(n => $("#content").html(renderErrorCard(n)));
    } else {
        return list(i, true);
    }
}

async function file(i) {
    const e = await getCookie("root_id") || "";
    $("#content").html('<div class="gdi-wrap text-center py-5"><div class="spinner-border text-primary" role="status"></div></div>');
    fetch("", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({path: i})
    }).then(t => t.json()).then(t => dispatchFileView(t, e)).catch(t => $("#content").html(renderErrorCard(t)));
}

function dispatchFileView(i, e) {
    const UI = window.UI || {};
    const t = i.mimeType;
    const n = i.fileExtension;
    
    if (t === "application/vnd.google-apps.folder") {
        window.location.href = window.location.pathname + "/";
        return;
    }
    
    const a = i.name;
    const c = encodeURIComponent(a);
    const l = formatFileSize(i.size);
    const d = UI.second_domain_for_dl ? UI.downloaddomain + i.link : window.location.origin + i.link;
    const o = i.id;
    
    if (t && GDOC_TYPES[t]) {
        file_workspace(a, l, t, d);
    } else if (FILE_TYPES.video.includes(n) || t?.includes("video")) {
        const s = i.thumbnailLink ? i.thumbnailLink.replace("s220", "s0") : UI.poster;
        file_video(a, c, l, s, d, t, o, e);
    } else if (FILE_TYPES.audio.includes(n) || t?.includes("audio")) {
        file_audio(a, c, l, d, o, e);
    } else if (FILE_TYPES.image.includes(n) || t?.includes("image")) {
        file_image(a, c, l, d, o, e);
    } else if (n === "pdf" || t?.includes("pdf")) {
        file_pdf(a, c, l, d, o, e);
    } else if (FILE_TYPES.code.includes(n)) {
        file_code(a, c, l, i.size, d, n, o, e);
    } else {
        file_others(a, c, l, d, o, e);
    }
}

function renderErrorCard(i) {
    return `<div class="gdi-wrap"><div class="gdi-viewer-card text-center py-5"><h4>Erro ao carregar conteúdo</h4><p class="text-muted">${escHtml(String(i))}</p><a href="/" class="gdi-btn gdi-btn-primary mt-3"><i class="bi bi-house"></i> Voltar ao Início</a></div></div>`;
}

function renderDownloadButtons(i, e) {
    return `
    <div class="d-flex align-items:center justify-content:between gap-3 mt-4 pt-3 border-top border-secondary">
      <span class="text-muted text-truncate" style="font-size:12px;max-width:60%;" title="${escHtml(i)}">${escHtml(i)}</span>
      <div class="d-flex gap-2">
        <button class="gdi-btn gdi-btn-ghost" onclick="copyShareUrl('${i}')"><i class="bi bi-clipboard"></i> Copiar Link</button>
        <a href="${i}" class="gdi-btn gdi-btn-primary" download><i class="bi bi-download"></i> Baixar Arquivo</a>
      </div>
    </div>`;
}

function copyShareUrl(i) {
    navigator.clipboard.writeText(i).then(() => showToast("Link copiado para a área de transferência!"));
}

function showToast(i) {
    let e = document.getElementById("gdi-toast-container");
    if (!e) {
        e = document.createElement("div");
        e.id = "gdi-toast-container";
        document.body.appendChild(e);
    }
    const t = document.createElement("div");
    t.className = "gdi-toast";
    t.innerHTML = `<i class="bi bi-check-circle-fill"></i> <span>${i}</span>`;
    e.appendChild(t);
    setTimeout(() => {
        t.classList.add("gdi-toast-out");
        setTimeout(() => t.remove(), 200);
    }, 3000);
}

function _viewerBreadcrumb() {
    return generateBreadcrumb(window.location.pathname);
}

function generateBreadcrumb(i) {
    const e = i.split("/");
    let t = "", n = "";
    for (let a = 0; a < e.length; a++) {
        let c = e[a];
        n += (a === 0 ? "" : "/") + c;
        const l = a === e.length - 1;
        let d;
        try { d = decodeURIComponent(c); } catch { d = c; }
        const s = d || "Home";
        const r = s.length > 20 ? s.slice(0, 16) + "\u2026" : s;
        if (l) {
            t += `<li class="gdi-bc-cur">${escHtml(r)}</li>`;
        } else {
            t += `<li><a href="${n ? n + "/" : "/"}">${escHtml(r)}</a></li><li class="gdi-bc-sep">/</li>`;
        }
    }
    return t;
}

function _viewerCard(icon, title, meta, body, footer) {
    return `
    <div class="gdi-wrap">
      <div class="gdi-breadcrumb-wrap mb-3"><ol class="gdi-bc">${_viewerBreadcrumb()}</ol></div>
      <div class="gdi-viewer-card">
        <div class="d-flex align-items:center gap-3 mb-4 pb-3 border-bottom border-secondary">
          <div style="font-size:28px;">${icon}</div>
          <div>
            <h4 class="mb-1" style="font-size:18px;font-weight:600;">${escHtml(title)}</h4>
            <span class="text-muted" style="font-size:12px;">${escHtml(meta)}</span>
          </div>
        </div>
        <div>${body}</div>
        ${footer || ''}
      </div>
    </div>`;
}

function file_others(i, e, t, n) {
    $("#content").html(_viewerCard('<i class="bi bi-file-earmark"></i>', i, t, '<p class="text-muted">Visualização não disponível para este formato. Utilize o botão abaixo para baixar.</p>', renderDownloadButtons(n, e)));
}

function file_workspace(i, e, t, n) {
    const a = GDOC_TYPES[t] || {name: "Documento Google", formats: []};
    const btns = a.formats.map(f => `<a class="gdi-btn gdi-btn-ghost" href="${n}&fmt=${f.ext}" download><i class="bi bi-file-earmark-arrow-down"></i> Baixar ${f.label}</a>`).join("");
    $("#content").html(_viewerCard('<i class="bi bi-file-earmark-text"></i>', i, e, `<p class="text-muted mb-4">Este é um arquivo integrado do Google Workspace (${a.name}).</p><div class="d-flex gap-2">${btns}</div>`, ""));
}

function file_code(i, e, t, n, a, c) {
    $("#content").html(_viewerCard('<i class="bi bi-code-slash"></i>', i, t, `<pre class="p-3 rounded" style="background:var(--gdi-bg);max-height:400px;overflow:auto;"><code id="editor">Carregando código...</code></pre>`, renderDownloadButtons(a, e)));
    if (n <= 2097152) {
        $.get(a, res => $("#editor").text(res)).fail(() => $("#editor").text("Falha ao carregar conteúdo do código."));
    } else {
        $("#editor").text("Arquivo muito grande para pré-visualização (máx 2MB).");
    }
}

// ============================================================
// PLAYER DE VÍDEO COMPLETO COM SUPORTE A ANOTAÇÕES E PROGRESSO
// ============================================================
function file_video(i, e, t, n, a, c, fileId) {
    const UI = window.UI || {};
    const playerType = window.player_config?.player || 'plyr';
    
    let playerHtml = '';
    if (playerType === 'plyr') {
        playerHtml = `<video id="player" playsinline controls autoplay data-poster="${n}"><source src="${a}" type="video/mp4"></video>`;
    } else {
        playerHtml = `<video id="player" controls autoplay style="width:100%;max-height:600px;background:#000;"><source src="${a}" type="video/mp4"></video>`;
    }
    
    const notesPanel = `
    <div class="mt-4 pt-3 border-top border-secondary">
        <div class="d-flex justify-content:between align-items:center mb-3">
            <h5 class="mb-0 fw-semibold" style="font-size:15px;"><i class="bi bi-journal-richtext text-primary me-2"></i>Anotações da Aula</h5>
            <span class="text-muted" style="font-size:12px;">Dica: Salve notas atreladas ao minuto atual do vídeo</span>
        </div>
        <div class="d-flex gap-2 mb-3">
            <input id="gdi-note-input" type="text" class="form-control bg-dark text-light border-secondary" placeholder="Digite sua anotação neste momento da aula..." onkeypress="if(event.key==='Enter')addVideoNote('${fileId}', '${escHtml(i)}')">
            <button class="gdi-btn gdi-btn-primary" onclick="addVideoNote('${fileId}', '${escHtml(i)}')"><i class="bi bi-plus-lg"></i> Adicionar</button>
        </div>
        <div id="gdi-notes-list" style="max-height:220px;overflow-y:auto;" class="d-flex flex-column gap-2"></div>
    </div>`;
    
    const body = `<div class="gdi-player-wrap mb-4">${playerHtml}</div>${notesPanel}`;
    $("#content").html(_viewerCard('<i class="bi bi-play-circle-fill text-primary"></i>', i, t, body, renderDownloadButtons(a, e)));
    
    // Inicializar Player e Tracking
    setTimeout(() => {
        let videoEl = document.getElementById('player');
        if (window.Plyr && document.getElementById('player')) {
            window._gdiPlayerInstance = new Plyr('#player');
        } else {
            window._gdiPlayerInstance = videoEl;
        }
        
        setupVideoProgressTracking(fileId, i, window.location.href);
        loadVideoNotes(fileId);
    }, 300);
}

function addVideoNote(videoId, videoName) {
    const input = document.getElementById('gdi-note-input');
    if (!input || !input.value.trim()) return;
    
    const player = window._gdiPlayerInstance;
    let currentTime = 0;
    if (player) {
        if (typeof player.currentTime === 'function') currentTime = player.currentTime();
        else if (player.currentTime) currentTime = player.currentTime;
    }
    
    const note = {
        text: input.value.trim(),
        timestamp: currentTime,
        formattedTime: formatTime(currentTime)
    };
    
    GDIUserSystem.addNote(videoId, note);
    input.value = '';
    loadVideoNotes(videoId);
    showToast('Anotação salva com sucesso!');
}

function loadVideoNotes(videoId) {
    const listEl = document.getElementById('gdi-notes-list');
    if (!listEl) return;
    
    const notes = GDIUserSystem.getNotes(videoId);
    if (notes.length === 0) {
        listEl.innerHTML = '<div class="text-muted text-center py-3" style="font-size:13px;">Nenhuma anotação registrada para esta aula ainda.</div>';
        return;
    }
    
    listEl.innerHTML = notes.map(n => `
        <div class="p-3 rounded d-flex justify-content:between align-items:center" style="background:var(--gdi-surface-hover);border:1px solid var(--gdi-border);">
            <div>
                <button class="badge bg-primary text-white border-0 mb-1" onclick="jumpToTimestamp(${n.timestamp})" style="cursor:pointer;"><i class="bi bi-play-fill"></i> ${n.formattedTime}</button>
                <div style="font-size:13px;">${escHtml(n.text)}</div>
            </div>
            <button class="btn btn-sm text-danger" onclick="deleteVideoNote('${videoId}', '${n.id}')" title="Excluir nota"><i class="bi bi-trash"></i></button>
        </div>
    `).join('');
}

function deleteVideoNote(videoId, noteId) {
    GDIUserSystem.removeNote(videoId, noteId);
    loadVideoNotes(videoId);
    showToast('Anotação removida.');
}

function jumpToTimestamp(seconds) {
    const player = window._gdiPlayerInstance;
    if (!player) return;
    if (typeof player.currentTime === 'function') player.currentTime(seconds);
    else if (player.currentTime) player.currentTime = seconds;
}

function setupVideoProgressTracking(videoId, videoName, videoUrl) {
    const player = window._gdiPlayerInstance;
    if (!player) return;
    
    let lastSaved = 0;
    const save = () => {
        let cur = 0, dur = 0;
        if (typeof player.currentTime === 'function') { cur = player.currentTime(); dur = player.duration(); }
        else if (player.currentTime) { cur = player.currentTime; dur = player.duration; }
        
        if (cur > 0 && dur > 0 && Math.abs(cur - lastSaved) >= 5) {
            GDIUserSystem.saveVideoProgress(videoId, { name: videoName, currentTime: cur, duration: dur, url: videoUrl });
            lastSaved = cur;
        }
    };
    
    setInterval(save, 3000);
    window.addEventListener('beforeunload', save);
}

