    $("#content").html(_viewerCard('<i class="bi bi-music-note-beamed text-pink"></i>', i, t, `<audio controls autoplay style="width:100%;margin:20px 0;"><source src="${n}"></audio>`, renderDownloadButtons(n, e)));
